//! The words of `gun_stats` that the executable holds rather than `gunstats.bin`: for each
//! gun type, what a shot costs the ship, the sound it makes and how often that sound is
//! heard.
//!
//! Generated by `src/tools/tablegen` from the payload executable's `gun_stats` at
//! 0x00500CA4 and its sound periods at 0x00508700. Do not edit by hand; run `make gun-tables`.

const guns = @import("../guns.zig");

/// What a gun type's record holds besides its figures from `gunstats.bin`.
pub const Static = struct {
    /// What a shot costs the ship.
    kind: guns.Kind,
    /// **Unknown.** Always the same as `_unknown_08`.
    _unknown_04: f32,
    /// **Unknown.**
    _unknown_08: f32,
    /// **Unknown.** Between 50 and 1400.
    _unknown_0c: f32,
    /// The sound a shot makes (`bullet_fire`).
    sound: i32,
};

/// Every gun type's, by its number. Type 0 is no gun: no muzzle may name it.
pub const gun_types = [16]Static{
    // 0x00
    .{ .kind = .energy, ._unknown_04 = 0, ._unknown_08 = 0, ._unknown_0c = 0, .sound = 0 },
    // 0x01
    .{ .kind = .energy, ._unknown_04 = 30, ._unknown_08 = 30, ._unknown_0c = 1200, .sound = 0 },
    // 0x02
    .{ .kind = .energy, ._unknown_04 = 30, ._unknown_08 = 30, ._unknown_0c = 800, .sound = 0 },
    // 0x03
    .{ .kind = .energy, ._unknown_04 = 64, ._unknown_08 = 64, ._unknown_0c = 50, .sound = 1 },
    // 0x04
    .{ .kind = .energy, ._unknown_04 = 50, ._unknown_08 = 50, ._unknown_0c = 1400, .sound = 2 },
    // 0x05
    .{ .kind = .energy, ._unknown_04 = 30, ._unknown_08 = 30, ._unknown_0c = 800, .sound = 3 },
    // 0x06
