    // 0x08
    .{ .kind = .rounds, ._unknown_04 = 30, ._unknown_08 = 30, ._unknown_0c = 800, .sound = 6 },
    // 0x09
    .{ .kind = .rounds, ._unknown_04 = 30, ._unknown_08 = 30, ._unknown_0c = 800, .sound = 7 },
